cTz(a){return A.f(a)+" \u0441\u0435\u0439\u0447\u0430\u0441 \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c. \u0414\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0435\u0441\u044c \u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0432 \u0447\u0430\u0442\u0435"},
cTH(a){return A.f(a)+" \u043f\u0440\u043e\u0441\u0438\u0442 \u0432\u0438\u0434\u0435\u043e\u043f\u043e\u043a\u0430\u0437"},
cTP(a){return"\u0421\u043c\u043e\u0442\u0440\u0438\u0442: "+A.f(a)},
cTX(a){return"\u0412\u044b \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u0432\u0438\u0434\u0435\u043e\u043f\u043e\u043a\u0430\u0437 \u2014 \u0436\u0434\u0451\u043c \u043e\u0442\u0432\u0435\u0442\u0430: "+A.f(a)},
cU5(a){return A.f(a)+" \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442"},
cUj(a){return"\u0418\u0418 \u0437\u0430\u043f\u043e\u043b\u043d\u0438\u043b \u043f\u043e\u0447\u0442\u0438 \u0432\u0441\u0451. \u041e\u0441\u0442\u0430\u043b\u043e\u0441\u044c: "+A.f(a)+" \u2014 \u0441\u043a\u0430\u0436\u0438\u0442\u0435 \u0438\u043b\u0438 \u0432\u0432\u0435\u0434\u0438\u0442\u0435."},
cUq(a){return A.f(a)+" \u043f\u043e \u0441\u0442\u0440\u0430\u043d\u0435 \xb7 \u0441\u043c\u0435\u043d\u0438\u0442\u044c"},
cUA(a){return"\u041e\u0441\u0442\u0430\u043b\u043e\u0441\u044c \u0441\u043a\u0430\u0437\u0430\u0442\u044c: "+A.f(a)},
cUI(a){return"\u041e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u0439 \u0432 \u0440\u0430\u0441\u0441\u043a\u0430\u0437\u0435: "+A.f(a)},
cUQ(a){return"\u041e\u0441\u0442\u0430\u043b\u043e\u0441\u044c: "+A.f(a)},
cUY(a){return"\u0413\u043e\u0432\u043e\u0440\u044e \u043d\u0430: "+A.f(a)},
cV5(a){return"\u041f\u043b\u043e\u0449\u0430\u0434\u044c: "+A.f(a)+" \u043c\xb2"},
cVd(a){return"\u0412\u0430\u043d\u043d\u044b\u0435: "+A.f(a)},
cVl(a){return"\u042d\u0442\u0430\u0436: "+A.f(a)},
cVu(a){return"\u0421\u043f\u0430\u043b\u044c\u043d\u0438: "+A.f(a)},
cVI(a){return"\u0414\u043e \u043c\u043e\u0440\u044f: "+A.f(a)+" \u043c\u0438\u043d"},
